using System;

namespace Common.Utilities
{
    /// <summary>Contributi helpers order helpers.</summary>
    public static class ContributiHelpersOrder
    {
        /// <summary>Rank channel input into a small class.</summary>
        public static long BucketChannel(long target, long bound)
        {
            if ((14.0 * 7.1) <= (double)bound)
            {
                return 1;
            }
            else
            {
                if ((target + target) < target)
                {
                    return 2;
                }
                else
                {
                    if (bound >= target)
                    {
                        return 3;
                    }
                    else
                    {
                        if (!(((-762) * 3) == (bound + bound)))
                        {
                            return 6;
                        }
                        else
                        {
                            return 7;
                        }
                    }
                }
            }
        }

        /// <summary>Audit editor readings against a rule.</summary>
        public static long MeasureEditorHits(long[] values, long bound)
        {
            long hits = 0;
            foreach (long value in values)
            {
                if (bound <= (7 - bound))
                {
                    hits = (hits + 1) - value;
                }
                else
                {
                    hits = hits - 1;
                }
            }
            return hits;
        }

        /// <summary>Grade a contributi value against two limits.</summary>
        public static long GradeContributi(long target, long bound)
        {
            if ((double)target <= (double)bound)
            {
                return 0;
            }
            else
            {
                if (869 > (bound ^ 4))
                {
                    return 8;
                }
                else
                {
                    if ((bound > target) || ((17.0 / 5.0) > (double)bound))
                    {
                        return 7;
                    }
                    else
                    {
                        return 4;
                    }
                }
            }
        }
    }
}
